import test from 'node:test';
import assert from 'node:assert/strict';
import { formatLabel, decoratedLabel } from '../src/format-label.js';
test('format valid label and preserve case', t => { assert.equal(formatLabel('MiXeD'), 'MiXeD'); t.diagnostic('BODY:format-valid'); });
test('reject blank label', t => { assert.throws(() => formatLabel('   '), /blank/); t.diagnostic('BODY:format-blank'); });
test('decorate with configured suffix', t => { assert.equal(decoratedLabel('hello'), 'hello!'); t.diagnostic('BODY:format-config'); });
test('trim surrounding whitespace', t => { assert.equal(formatLabel('  hello  '), 'hello'); t.diagnostic('BODY:format-whitespace'); });
test('decorate trimmed label', () => assert.equal(decoratedLabel('  MiXeD  '), 'MiXeD!'));
test('decoration rejects blank', () => assert.throws(() => decoratedLabel('  '), /blank/));

